        metaClient.getActiveTimeline().transitionRequestedToInflight(new HoodieInstant(State.REQUESTED, HoodieTimeline.DELTA_COMMIT_ACTION, newCommitTime), Option.empty());
        writeClient.commit(newCommitTime, jsc.emptyRDD(), Option.empty());
